-- Generated by scripts/db/snapshot-functions.ts -- do not edit by hand.
-- Redefine a function from this file, never from an old migration.

-- update_order_status_with_fabric(p_order_id uuid, p_status text, p_status_key text, p_fabric_lines jsonb, p_notes text, p_op_id uuid, p_history_note text)
CREATE OR REPLACE FUNCTION public.update_order_status_with_fabric(p_order_id uuid, p_status text, p_status_key text, p_fabric_lines jsonb, p_notes text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid, p_history_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c_max_per_piece CONSTANT numeric := 15;
  c_max_legacy    CONSTANT numeric := 100;
  v_tenant    uuid;
  v_role      text;
  v_kind      text;
  v_deducted  timestamptz;
  v_notes     text;
  v_order_br  uuid;
  v_meta      jsonb;
  v_line      jsonb;
  v_meters    numeric;
  v_stored    numeric;
  v_qty       numeric;
  v_fabric    uuid;
  v_changes   text := '';
  v_note      text := p_history_note;
  -- seen-cutting-fabric-pos-orders-fix-task.md: a POS sale's lines
  v_pos       boolean;
  v_row_id    uuid;
  v_row_fab   uuid;
  v_taken     numeric;
  v_diff      numeric;
  v_move      numeric;
  v_have      numeric;
  v_branch    uuid;
  v_strategy  text;
  v_name      text;
  v_any_taken boolean := false;
  v_op_tag    text := COALESCE(p_op_id::text, gen_random_uuid()::text);
BEGIN
  v_tenant := public.app_current_tenant_id();
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_role := public.app_current_role();
  IF NOT public.app_has_permission('orders.update_status') THEN
    RAISE EXCEPTION 'لا تملك صلاحية تعديل حالة الطلب' USING ERRCODE = '42501';
  END IF;

  -- The same request again (same p_op_id): nothing moves twice.
  IF p_op_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.stock_operations
     WHERE operation_id = 'update_order_status:' || p_op_id::text AND tenant_id = v_tenant
  ) THEN
    RETURN public.update_order_status(p_order_id, p_status, p_status_key, p_notes, p_op_id, p_history_note);
  END IF;

  SELECT kind, fabric_deducted_at, notes, branch_id INTO v_kind, v_deducted, v_notes, v_order_br
    FROM public.orders
   WHERE id = p_order_id AND tenant_id = v_tenant
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  -- A POS sale keeps its lines in order_items (like a tailoring order) and
  -- may have had its cloth taken at the sale: its lines are checked by
  -- line_key, and only the difference from what was taken moves.
  v_pos := v_kind = 'pos_sale' OR (v_kind IS DISTINCT FROM 'tailoring' AND EXISTS (
    SELECT 1 FROM public.order_items
     WHERE order_id = p_order_id AND tenant_id = v_tenant AND type = 'custom' AND fabric_id IS NOT NULL));

  IF v_pos AND jsonb_typeof(p_fabric_lines) = 'array'
     AND p_status::order_status >= 'cutting'::order_status
     AND p_status::order_status <> 'cancelled'::order_status THEN

    FOR v_line IN SELECT * FROM jsonb_array_elements(p_fabric_lines) LOOP
      v_meters := NULLIF(v_line->>'meters', '')::numeric;
      IF v_meters IS NULL OR v_meters < 0 THEN
        RAISE EXCEPTION 'كمية القماش غير صالحة' USING ERRCODE = '22023';
      END IF;

      v_row_id := NULL;
      BEGIN
        v_row_id := NULLIF(v_line->>'line_key', '')::uuid;
      EXCEPTION WHEN invalid_text_representation THEN
        v_row_id := NULL;
      END;
      SELECT id, fabric_id, COALESCE(consumed_meters, 0), quantity, COALESCE(fabric_taken_meters, 0)
        INTO v_row_id, v_row_fab, v_stored, v_qty, v_taken
        FROM public.order_items
       WHERE id = v_row_id AND order_id = p_order_id AND tenant_id = v_tenant
         AND type = 'custom' AND fabric_id IS NOT NULL
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'سطر القماش هذا ليس من أصناف الطلب. حدّث الصفحة ثم أعد المحاولة.'
          USING ERRCODE = '22023', HINT = 'fabric_line_mismatch';
      END IF;

      IF v_meters > c_max_per_piece * GREATEST(v_qty, 1) THEN
        RAISE EXCEPTION 'كمية القماش (% م) أكبر من الحد المسموح لهذا السطر (% م)',
          v_meters, c_max_per_piece * GREATEST(v_qty, 1) USING ERRCODE = '22023';
      END IF;

      v_diff := v_meters - v_taken;
      v_move := 0;
      IF v_diff <> 0 THEN
        -- The branch, as deduct_order_fabric resolves it.
        IF v_branch IS NULL THEN
          SELECT inventory_strategy INTO v_strategy FROM public.tenants WHERE id = v_tenant;
          IF COALESCE(v_strategy, 'centralized') = 'centralized' THEN
            SELECT id INTO v_branch FROM public.branches WHERE tenant_id = v_tenant AND is_main = true LIMIT 1;
            IF v_branch IS NULL THEN
              RAISE EXCEPTION 'المستودع الرئيسي غير موجود' USING ERRCODE = '22023';
            END IF;
          ELSE
            v_branch := COALESCE(v_order_br, (SELECT branch_id FROM public.staff WHERE id = public.app_current_staff_id()));
            IF v_branch IS NULL THEN
              RAISE EXCEPTION 'لم يُحدَّد فرع لخصم القماش' USING ERRCODE = '22023';
            END IF;
          END IF;
        END IF;

        IF v_diff > 0 THEN
          -- More than was taken: the extra comes out, through the same
          -- shortage path as any cutting deduction.
          SELECT COALESCE(SUM(quantity), 0) INTO v_have FROM public.branch_inventory
           WHERE tenant_id = v_tenant AND branch_id = v_branch AND item_id = v_row_fab AND variant_id IS NULL;
          IF v_have < v_diff THEN
            SELECT name INTO v_name FROM public.inventory_items WHERE id = v_row_fab;
            IF current_setting('seen.allow_fabric_shortage', true) IS DISTINCT FROM 'on' THEN
              RAISE EXCEPTION 'القماش «%» غير كافٍ: المطلوب % م والمتاح % م', COALESCE(v_name, ''), v_diff, GREATEST(v_have, 0)
                USING ERRCODE = '23514', HINT = 'fabric_shortage';
            END IF;
            v_move := GREATEST(v_have, 0);
            INSERT INTO public.fabric_shortages (tenant_id, order_id, fabric_id, branch_id, needed, deducted, created_by)
            VALUES (v_tenant, p_order_id, v_row_fab, v_branch, v_diff, v_move, public.app_actor_staff_id());
          ELSE
            v_move := v_diff;
          END IF;
          IF v_move > 0 THEN
            PERFORM public.apply_stock_movement(
              'order:' || p_order_id::text || ':line:' || v_row_id::text || ':cut:' || v_op_tag,
              v_branch, v_row_fab, -v_move, 'deduction', p_order_id, 'order');
          END IF;
        ELSE
          -- Less than was taken at the sale: the rest goes back to stock.
          v_move := v_diff;
          PERFORM public.apply_stock_movement(
            'order:' || p_order_id::text || ':line:' || v_row_id::text || ':cut:' || v_op_tag,
            v_branch, v_row_fab, -v_diff, 'adjustment', p_order_id, 'order');
        END IF;
      END IF;

      IF v_meters IS DISTINCT FROM v_stored OR v_move <> 0 THEN
        v_changes := v_changes || CASE WHEN v_changes = '' THEN '' ELSE '، ' END
                     || v_taken::text || ' ← ' || v_meters::text || ' م';
      END IF;
      UPDATE public.order_items
         SET consumed_meters = v_meters,
             fabric_taken_meters = NULLIF(v_taken + v_move, 0)
       WHERE id = v_row_id;
      IF v_taken + v_move > 0 THEN
        v_any_taken := true;
      END IF;
    END LOOP;

    IF v_any_taken THEN
      UPDATE public.orders SET fabric_deducted_at = COALESCE(fabric_deducted_at, now()) WHERE id = p_order_id;
    END IF;

  ELSIF v_deducted IS NULL AND jsonb_typeof(p_fabric_lines) = 'array'
     AND p_status::order_status >= 'cutting'::order_status
     AND p_status::order_status <> 'cancelled'::order_status THEN

    IF v_kind = 'tailoring' THEN
      FOR v_line IN SELECT * FROM jsonb_array_elements(p_fabric_lines) LOOP
        v_meters := NULLIF(v_line->>'meters', '')::numeric;
        IF v_meters IS NULL OR v_meters < 0 THEN
          RAISE EXCEPTION 'كمية القماش غير صالحة' USING ERRCODE = '22023';
        END IF;

        -- The line must be one of this order's own stock-cloth lines.
        SELECT COALESCE(consumed_meters, 0), quantity INTO v_stored, v_qty
          FROM public.order_items
         WHERE id = NULLIF(v_line->>'line_key', '')::uuid
           AND order_id = p_order_id AND tenant_id = v_tenant
           AND type = 'custom' AND fabric_id IS NOT NULL;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'سطر القماش هذا ليس من أصناف الطلب. حدّث الصفحة ثم أعد المحاولة.'
            USING ERRCODE = '22023', HINT = 'fabric_line_mismatch';
        END IF;

        IF v_meters > c_max_per_piece * GREATEST(v_qty, 1) THEN
          RAISE EXCEPTION 'كمية القماش (% م) أكبر من الحد المسموح لهذا السطر (% م)',
            v_meters, c_max_per_piece * GREATEST(v_qty, 1) USING ERRCODE = '22023';
        END IF;

        IF v_meters IS DISTINCT FROM v_stored THEN
          v_changes := v_changes || CASE WHEN v_changes = '' THEN '' ELSE '، ' END
                       || v_stored::text || ' ← ' || v_meters::text || ' م';
          UPDATE public.order_items
             SET consumed_meters = v_meters
           WHERE id = (v_line->>'line_key')::uuid;
        END IF;
      END LOOP;

    ELSE
      -- An older order keeps its lines inside `notes`. Read them from the
      -- STORED notes (not from p_notes, which the caller supplies) and accept
      -- a deduction only for a cloth one of those lines names.
      v_meta := NULL;
      IF v_notes LIKE '\_\_ORDER\_%:{%' THEN
        BEGIN
          v_meta := substring(v_notes FROM position(':' IN v_notes) + 1)::jsonb;
        EXCEPTION WHEN OTHERS THEN
          v_meta := NULL;
        END;
      END IF;
      IF v_meta IS NULL OR jsonb_typeof(v_meta->'items') <> 'array' THEN
        RAISE EXCEPTION 'تعذّر التحقق من أصناف الطلب لخصم القماش. حدّث الصفحة ثم أعد المحاولة.'
          USING ERRCODE = '22023', HINT = 'fabric_lines_unknown';
      END IF;

      FOR v_line IN SELECT * FROM jsonb_array_elements(p_fabric_lines) LOOP
        v_meters := NULLIF(v_line->>'meters', '')::numeric;
        v_fabric := NULLIF(v_line->>'fabric_id', '')::uuid;
        IF v_meters IS NULL OR v_meters < 0 OR v_meters > c_max_legacy THEN
          RAISE EXCEPTION 'كمية القماش غير صالحة' USING ERRCODE = '22023';
        END IF;
        IF v_fabric IS NULL OR NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(v_meta->'items') it
           WHERE it->>'fabricId' = v_fabric::text
        ) THEN
          RAISE EXCEPTION 'هذا القماش ليس من أصناف الطلب. حدّث الصفحة ثم أعد المحاولة.'
            USING ERRCODE = '22023', HINT = 'fabric_line_mismatch';
        END IF;
      END LOOP;
      -- S-08: however many lines are sent, a cloth gets no more than 15 m a
      -- piece of the order's items that name it.
      IF EXISTS (
        SELECT 1 FROM (
          SELECT l->>'fabric_id' AS f, sum(NULLIF(l->>'meters', '')::numeric) AS m
            FROM jsonb_array_elements(p_fabric_lines) l GROUP BY 1
        ) req
        WHERE req.m > c_max_per_piece * GREATEST(coalesce((
          SELECT sum(GREATEST(coalesce(NULLIF(it->>'quantity', '')::numeric, 1), 1))
            FROM jsonb_array_elements(v_meta->'items') it WHERE it->>'fabricId' = req.f), 1), 1)
      ) THEN
        RAISE EXCEPTION 'كمية القماش أكبر من المسموح لأصناف الطلب' USING ERRCODE = '22023';
      END IF;
      PERFORM public.deduct_order_fabric(p_order_id, p_fabric_lines);
    END IF;
  END IF;

  IF v_changes <> '' THEN
    v_note := COALESCE(NULLIF(p_history_note, '') || ' | ', '') || 'تعديل كمية القماش عند القص: ' || v_changes;
  END IF;

  RETURN public.update_order_status(p_order_id, p_status, p_status_key, p_notes, p_op_id, v_note);
END $function$;
